(() => {const previous=sqRefsOf;window.sqRefsOf=function(id){const refs=previous(id),sequence=sqFind(id);HTWorkflow.services().filter(s=>s.sequenceId===id||s.sequence===id||s.sequence===sequence?.name).forEach(s=>refs.push({seqId:id,kind:'service',name:s.title}));HTWorkflow.layers().filter(l=>l.services?.some(s=>s.sequence===id||s.sequence===sequence?.name)).forEach(l=>refs.push({seqId:id,kind:'layer',name:l.name}));return refs.filter((r,i,a)=>a.findIndex(x=>x.kind===r.kind&&x.name===r.name)===i);};sqRender();})();
